<html lang="en">
<head>
<meta charset="utf-8">
<title>Coding AI Leaderboard - Infographic</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700;800&display=swap');

  :root {
    --bg-deep: #080c12;
    --bg-card: #111820;
    --bg-table-row: #0f161f;
    --bg-table-alt: #131c28;
    --border: #1e2938;
    --text-primary: #e8edf4;
    --text-secondary: #8896a7;
    --text-dim: #5a6778;
    --blue: #3b8bff;
    --blue-glow: rgba(59, 139, 255, 0.15);
    --green: #26c97e;
    --green-glow: rgba(38, 201, 126, 0.15);
    --amber: #f0a828;
    --amber-glow: rgba(240, 168, 40, 0.15);
    --purple: #8b6ff7;
    --purple-glow: rgba(139, 111, 247, 0.15);
    --pink: #e85d9a;
    --pink-glow: rgba(232, 93, 154, 0.15);
    --cyan: #2ec4c7;
    --cyan-glow: rgba(46, 196, 199, 0.15);
    --red: #f04a5a;
    --teal: #3ab8a0;
  }

  body {
    background: #1a1a2e;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    min-height: 100vh;
    padding: 0;
  }

  .poster {
    width: 1200px;
    height: 1920px;
    background: var(--bg-deep);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: var(--text-primary);
    position: relative;
    overflow: hidden;
    flex-shrink: 0;
  }

  /* Background grid pattern */
  .poster::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(rgba(59, 139, 255, 0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(59, 139, 255, 0.03) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
    z-index: 0;
  }

  /* Top glow accent */
  .poster::after {
    content: '';
    position: absolute;
    top: -200px;
    left: 50%;
    transform: translateX(-50%);
    width: 800px;
    height: 400px;
    background: radial-gradient(ellipse, rgba(59, 139, 255, 0.08) 0%, transparent 70%);
    pointer-events: none;
    z-index: 0;
  }

  /* Content wrapper */
  .content {
    position: relative;
    z-index: 1;
    padding: 60px 70px 50px;
    height: 100%;
    display: flex;
    flex-direction: column;
  }

  /* ========== HEADER ========== */
  .header {
    text-align: center;
    margin-bottom: 8px;
  }

  .header-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 24px;
    padding: 6px 20px;
    margin-bottom: 18px;
  }

  .header-badge svg { width: 18px; height: 18px; fill: var(--text-secondary); }
  .header-badge span {
    font-size: 13px;
    font-family: 'JetBrains Mono', 'Courier New', monospace;
    color: var(--text-secondary);
    letter-spacing: 0.5px;
  }

  .header h1 {
    font-family: 'Inter', sans-serif;
    font-weight: 900;
    font-size: 54px;
    letter-spacing: -1px;
    line-height: 1.15;
    background: linear-gradient(135deg, #e8edf4 0%, #58a6ff 50%, #3fb950 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 10px;
  }

  .header .subtitle {
    font-size: 17px;
    color: var(--text-secondary);
    font-weight: 500;
    letter-spacing: 0.3px;
  }

  .header .subtitle .date-range {
    color: var(--blue);
    font-weight: 600;
  }

  /* Divider */
  .divider {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 22px 0;
  }

  .divider-line {
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--border), transparent);
  }

  .divider-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--blue);
    box-shadow: 0 0 8px var(--blue);
  }

  /* ========== METRICS CARDS ========== */
  .metrics-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 28px;
  }

  .metric-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 22px 20px;
    position: relative;
    overflow: hidden;
    transition: none;
  }

  .metric-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
  }

  .metric-card:nth-child(1)::before { background: var(--blue); }
  .metric-card:nth-child(2)::before { background: var(--green); }
  .metric-card:nth-child(3)::before { background: var(--purple); }
  .metric-card:nth-child(4)::before { background: var(--amber); }

  .metric-card .metric-icon {
    font-size: 20px;
    margin-bottom: 8px;
  }

  .metric-card .metric-value {
    font-family: 'JetBrains Mono', 'Courier New', monospace;
    font-weight: 800;
    font-size: 38px;
    letter-spacing: -1px;
    line-height: 1;
    margin-bottom: 6px;
  }

  .metric-card:nth-child(1) .metric-value { color: var(--blue); }
  .metric-card:nth-child(2) .metric-value { color: var(--green); }
  .metric-card:nth-child(3) .metric-value { color: var(--purple); }
  .metric-card:nth-child(4) .metric-value { color: var(--amber); }

  .metric-card .metric-label {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-primary);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 4px;
  }

  .metric-card .metric-context {
    font-size: 12px;
    color: var(--text-dim);
    line-height: 1.4;
  }

  /* ========== SECTION HEADERS ========== */
  .section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
  }

  .section-header .section-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    font-weight: 700;
    color: var(--blue);
    background: var(--blue-glow);
    padding: 4px 10px;
    border-radius: 6px;
    border: 1px solid rgba(59, 139, 255, 0.25);
  }

  .section-header h2 {
    font-size: 20px;
    font-weight: 700;
    letter-spacing: -0.3px;
  }

  /* ========== RANKING TABLE ========== */
  .ranking-section {
    flex: 1;
    display: flex;
    flex-direction: column;
    margin-bottom: 20px;
  }

  .table-container {
    flex: 1;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 14px;
    overflow: hidden;
  }

  .table-header {
    display: grid;
    grid-template-columns: 60px 50px 1fr 60px 130px;
    padding: 14px 24px;
    background: rgba(255,255,255,0.02);
    border-bottom: 1px solid var(--border);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-dim);
  }

  .table-body {
    overflow: hidden;
  }

  .table-row {
    display: grid;
    grid-template-columns: 60px 50px 1fr 60px 130px;
    padding: 11px 24px;
    border-bottom: 1px solid rgba(30, 41, 56, 0.4);
    align-items: center;
    font-size: 14px;
  }

  .table-row:nth-child(odd) { background: var(--bg-table-row); }
  .table-row:nth-child(even) { background: var(--bg-table-alt); }

  .table-row:last-child { border-bottom: none; }

  .rank-num {
    font-family: 'JetBrains Mono', monospace;
    font-weight: 700;
    font-size: 15px;
    color: var(--text-secondary);
  }

  .rank-num.top1 { color: var(--amber); font-size: 17px; }
  .rank-num.top2 { color: #c0c8d4; }
  .rank-num.top3 { color: #c8906a; }

  .trend {
    font-family: 'JetBrains Mono', monospace;
    font-weight: 700;
    font-size: 13px;
    text-align: center;
  }
  .trend.up { color: var(--green); }
  .trend.down { color: var(--red); }
  .trend.stable { color: var(--text-dim); }
  .trend.new { color: var(--cyan); }

  .repo-info {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .repo-name {
    font-family: 'JetBrains Mono', 'Courier New', monospace;
    font-weight: 600;
    font-size: 13.5px;
    color: var(--text-primary);
  }

  .repo-owner {
    color: var(--text-dim);
  }

  .category-tag {
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    padding: 3px 8px;
    border-radius: 5px;
    white-space: nowrap;
