  .tag-agent { background: rgba(59,139,255,0.15); color: var(--blue); border: 1px solid rgba(59,139,255,0.3); }
  .tag-claude { background: rgba(38,201,126,0.12); color: var(--green); border: 1px solid rgba(38,201,126,0.25); }
