    font-family: 'JetBrains Mono', monospace;
    font-weight: 700;
    font-size: 14px;
    color: var(--amber);
    text-align: right;
  }

  /* Highlight row for #1 */
  .table-row.row-top1 {
    background: rgba(240,168,40,0.04);
    border-left: 3px solid var(--amber);
  }

  /* ========== THEMES SECTION ========== */
  .themes-section {
    margin-bottom: 18px;
