  .theme-clusters {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }

  .theme-cluster-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px 18px;
  }

  .theme-cluster-card .cluster-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 10px;
  }

  .cluster-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
  }
  .cluster-dot.agent { background: var(--blue); box-shadow: 0 0 8px var(--blue); }
  .cluster-dot.claude { background: var(--green); box-shadow: 0 0 8px var(--green); }
  .cluster-dot.util  { background: var(--amber); box-shadow: 0 0 8px var(--amber); }

  .cluster-title {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
  }

  .cluster-stats {
    display: flex;
    gap: 16px;
    margin-bottom: 8px;
  }

  .cluster-stat-val {
    font-family: 'JetBrains Mono', monospace;
    font-weight: 800;
    font-size: 22px;
    line-height: 1;
  }

  .cluster-stat-lbl {
    font-size: 10px;
    color: var(--text-dim);
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .cluster-repos {
    font-size: 11px;
    color: var(--text-secondary);
    line-height: 1.6;
  }

  /* ========== TAKEAWAYS ========== */
  .takeaways-section {
    margin-bottom: 14px;
