  .takeaway-list {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }

  .takeaway-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px 18px;
    position: relative;
  }

  .takeaway-num {
    font-family: 'JetBrains Mono', monospace;
    font-weight: 800;
    font-size: 13px;
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    margin-bottom: 10px;
  }
  .takeaway-card:nth-child(1) .takeaway-num { background: var(--blue-glow); color: var(--blue); }
  .takeaway-card:nth-child(2) .takeaway-num { background: var(--green-glow); color: var(--green); }
  .takeaway-card:nth-child(3) .takeaway-num { background: var(--amber-glow); color: var(--amber); }

  .takeaway-text {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-primary);
    line-height: 1.5;
    margin-bottom: 4px;
  }

  .takeaway-detail {
    font-size: 11px;
    color: var(--text-dim);
    line-height: 1.5;
  }

  /* ========== FOOTER ========== */
  .footer {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    padding-top: 8px;
  }

  .footer-item {
    font-size: 11px;
