const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for fonts to load
  await page.waitForTimeout(3000);

  // Get the poster element and screenshot it
  const poster = await page.$('.poster');
  if (!poster) {
    console.error('Poster element not found');
    process.exit(1);
  }

  await poster.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png'
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();

